  const formatDataCell = (value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return value;

    // Check if it's likely an index (integer)
    // If it parses to an integer (e.g. 1.255e+03 -> 1255), return it as a simple string "1255"
    if (Number.isInteger(num)) return num.toString(); 

    // Use toFixed to avoid scientific notation for small numbers, remove trailing zeros
    // But ensure at least one decimal digit if it was a float
    let formatted = num.toFixed(10).replace(/\.?0+$/, "");

    return formatted;
  };

  const handleImportData = async () => {
      try {
          if (importFormat === 'PalmSens4') {
              const lines = importText.trim().split('\n');
              const headerIndex = lines.findIndex(l => l.includes('potential/V') && l.includes('current/µA'));

              if (headerIndex === -1) {
                  alert("Invalid PalmSens4 format: Could not find header row.");
                  return;
              }

              const headerLine = lines[headerIndex];
              // Detect separator (tab or comma)
              const sep = headerLine.includes('\t') ? '\t' : ',';
              const headers = headerLine.split(sep).map(h => h.trim());

              const voltIndex = headers.indexOf('potential/V');
              const currIndex = headers.indexOf('current/µA');

              if (voltIndex === -1 || currIndex === -1) {
                   alert("Invalid PalmSens4 format: Missing 'potential/V' or 'current/µA' columns.");
                   return;
              }

              const voltages: number[] = [];
              const currents: number[] = [];

              for (let i = headerIndex + 1; i < lines.length; i++) {
                  const line = lines[i].trim();
                  if (!line) continue;

                  // PalmSens rows might end with empty tabs, splitting ensures we get all cols
                  const parts = line.split(sep);

                  if (parts.length > Math.max(voltIndex, currIndex)) {
                      const vVal = parseFloat(parts[voltIndex]); // in Volts
                      const cVal = parseFloat(parts[currIndex]); // in uA

                      if (!isNaN(vVal) && !isNaN(cVal)) {
                          voltages.push(vVal * 1000); // Convert to mV
                          currents.push(cVal);
                      }
                  }
              }

              if (voltages.length === 0) {
                  alert("No valid data points found.");
                  return;
              }

              // Send to backend
              const response = await axios.post(`${API_URL}/api/import`, {
                  deviceName: 'PalmSens4',
                  voltages,
                  currents
              });

              if (response.data.success) {
                  alert("Import successful!");
                  setShowImportModal(false);
                  setImportText('');
                  // Trigger refresh is handled by the polling effect
              }
          }
      } catch (error: any) {
          console.error("Import failed:", error);
          alert(`Import failed: ${error.message}`);
      }
  };

