  const getTraces = (type: 'swv' | 'raw' | 'voltage') => {
      const traces: any[] = [];

      let baseData: PlotData | null = null;
      let title = selectedEntry || 'Current';

      if (type === 'swv') {
          if (swvVisibility.diff && swvPlotData) {
              traces.push({
                  x: swvPlotData.x,
                  y: swvPlotData.y,
                  type: 'scatter',
                  mode: 'lines+markers',
